/* Commodore VIC-20 (PAL): see vic20.h.
 * Zero static .bss footprint: all RAM, ROM, cartridge, disk and video/audio buffers live in KSEG0(EMU_RAM_PHYS).
 */
#pragma GCC optimize("O2")
#include "vic20.h"

#ifndef VIC20_HOST
#include "hw.h"
#endif

#define VIC20_HTOTAL     71u
#define VIC20_VTOTAL     312u
#define VIC20_FRAME_CYC  (VIC20_HTOTAL * VIC20_VTOTAL) /* 22,152 cycles @ 1,108,405 Hz */
#define VIC20_CLOCK_HZ   1108405u
#define VIC20_VIS_X0     7u                            /* 7..62 = 56 ticks * 4 px = 224 px */
#define VIC20_VIS_X1     63u
#define VIC20_VIS_Y0     19u                           /* crt_y 19..258 = 240 PAL lines */
#define VIC20_VIS_Y1     259u
#define VIC20_RING_LEN   4096u
#define VIC20_MAX_PRG    0x9000u

/* Expansion RAM bitmask */
#define EXP_3K   0x01u   /* $0400..$0FFF */
#define EXP_8K   0x02u   /* $2000..$3FFF (BLK1) */
#define EXP_16K  0x04u   /* $4000..$5FFF (BLK2) */
#define EXP_24K  0x08u   /* $6000..$7FFF (BLK3) */
#define EXP_32K  0x10u   /* $A000..$BFFF (BLK5 RAM) */

/* Cartridge ROM bitmask */
#define CART_2000 0x01u
#define CART_4000 0x02u
#define CART_6000 0x04u
#define CART_A000 0x08u

struct vic20_ws {
    u8 ram_0k[0x0400];                  /* $0000..$03FF (1 KB system RAM) */
    u8 ram_3k[0x0C00];                  /* $0400..$0FFF (+3 KB RAM expansion) */
    u8 ram_main[0x1000];                /* $1000..$1FFF (4 KB main RAM) */
    u8 ram_exp[4][0x2000];              /* BLK1 ($2000), BLK2 ($4000), BLK3 ($6000), BLK5 ($A000) */
    u8 cart_rom[4][0x2000];             /* Cartridge ROM blocks ($2000, $4000, $6000, $A000) */
    u8 color_ram[0x0400];               /* $9400..$97FF (1K x 4-bit color RAM) */
    u8 ram_io[0x0800];                  /* $9800..$9FFF (I/O2 + I/O3 RAM) */
    u8 rom_char[0x1000];                /* $8000..$8FFF (4 KB Character ROM) */
    u8 rom_basic[0x2000];               /* $C000..$DFFF (8 KB BASIC V2 ROM) */
    u8 rom_kernal[0x2000];              /* $E000..$FFFF (8 KB PAL KERNAL ROM) */
    u8 prg_buf[VIC20_MAX_PRG];          /* Staged .prg payload for post-boot injection */
    u16 fb[VIC20_W * VIC20_H];          /* Rendered RGB15 frame (0bbbbbgggggrrrrr) */
    s16 snd_ring[VIC20_RING_LEN];
    u16 hw_pal[16];
    u8 sav_dummy[16];
};

#ifdef VIC20_HOST
static struct vic20_ws vic20_host_ws;
#define WS (&vic20_host_ws)
#else
#define WS ((struct vic20_ws *)KSEG0(EMU_RAM_PHYS))
#endif

#define RGB15_VIC(r, g, b) ((u16)((((r) >> 3) & 31u) | ((((g) >> 3) & 31u) << 5) | ((((b) >> 3) & 31u) << 10)))

